from tqdm import tqdm


def build_progress_bar(total_tokens: int, description: str) -> "tqdm[None]":
    return tqdm(
        total=total_tokens,
        desc=description,
        unit="tok",
        unit_scale=True,
        dynamic_ncols=True,
        smoothing=0.05,
        mininterval=1.0,
    )


def emit_log_line(bar: "tqdm[None]", message: str) -> None:
    bar.write(message)
